<div class="withdrawal-email-otp"><input type="hidden" name="otp_challenge_id" value="{{ (int)old('position_id',0)===($otpPosition??0) && is_numeric(old('otp_challenge_id'))?(int)old('otp_challenge_id'):'' }}"><button type="button" class="send-withdrawal-otp">Send Email OTP</button><label>Email OTP <input name="withdrawal_otp" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required></label><p class="withdrawal-otp-status" role="status"></p></div>
@once
<script>document.addEventListener('click',async event=>{const b=event.target.closest('.send-withdrawal-otp');if(!b)return;const form=b.closest('form'),status=form.querySelector('.withdrawal-otp-status');b.disabled=true;status.textContent='Sending email OTP…';const data={};for(const key of ['amount','request_key','usdt_wallet_id','position_id','expected_fee_percent']){const field=form.elements.namedItem(key);if(field&&field.value)data[key]=field.value;}try{const r=await fetch({{ Illuminate\Support\Js::from(route('member.withdrawal-otp.send')) }},{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':form.querySelector('[name=_token]').value},body:JSON.stringify(data)});const result=await r.json();if(!r.ok)throw Error(Object.values(result.errors||{}).flat().join(' ')||result.message||'Email could not be sent.');form.elements.otp_challenge_id.value=result.challenge_id;status.textContent=result.message;status.style.color='#86efac';}catch(e){status.textContent=e.message;status.style.color='#fda4af';}finally{b.disabled=false;}});</script>
@endonce
